result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "score.py", "content": """"Before/after scorecard for the messy-CSV normalizer.

Metrics per stage:
  - rows: int
  - duplicate_rate: fraction of rows whose canonical email was already seen
  - format_compliance: per-field fraction of values already in canonical form
      phone : matches ^\+1\d{10}$
      name  : trimmed, single-spaced, title-cased
      email : lowercase and matches basic email pattern

Usage: python score.py original.csv normalized.csv scorecard.json
"""
import csv
import json
import sys

from normalize import E164_RE, EMAIL_RE


def load_rows(path):
    with open(path, newline="", encoding="utf-8") as fh:
        return [
            {k: (v or "") for k, v in row.items()}
            for row in csv.DictReader(fh)
        ]


def name_is_compliant(name):
    s = name.strip()
    return (
        bool(s)
        and s == name                      # no stray outer whitespace
        and "  " not in s                  # no doubled inner spaces
        and s == s.title()                 # canonical title case
    )


def metrics(rows):
    total = len(rows)
    if total == 0:
        return {"rows": 0, "duplicate_rate": 0.0,
                "format_compliance": {"phone": 0.0, "name": 0.0, "email": 0.0}}

    seen = set()
    dupes = 0
    phone_ok = name_ok = email_ok = 0
    for row in rows:
        email = row.get("email", "").strip().lower()
        if email in seen:
            dupes += 1
        else:
            seen.add(email)

        if E164_RE.match(row.get("phone", "").strip()):
            phone_ok += 1
        if name_is_compliant(row.get("name", "")):
            name_ok += 1
        raw_email = row.get("email", "")
        if EMAIL_RE.match(raw_email.strip()) and raw_email.strip() == raw_email.strip().lower():
            email_ok += 1

    return {
        "rows": total,
        "duplicate_rate": round(dupes / total, 6),
        "format_compliance": {
            "phone": round(phone_ok / total, 6),
            "name": round(name_ok / total, 6),
            "email": round(email_ok / total, 6),
        },
    }


def build_scorecard(before_csv, after_csv):
    return {"before": metrics(load_rows(before_csv)),
            "after": metrics(load_rows(after_csv))}


if __name__ == "__main__":
    before_csv = sys.argv[1] if len(sys.argv) > 1 else "leads.csv"
    after_csv = sys.argv[2] if len(sys.argv) > 2 else "leads_normalized.csv"
    out_json = sys.argv[3] if len(sys.argv) > 3 else "scorecard.json"
    card = build_scorecard(before_csv, after_csv)
    with open(out_json, "w", encoding="utf-8") as fh:
        json.dump(card, fh, indent=2)
    print(json.dumps(card, indent=2))
"})
